using System;using System.Xml.Linq;
class Test{static int count;static void Check(bool x,string why){if(!x)throw new Exception(count+" "+why);count++;}static void Main(string[] args){var policy=XDocument.Load(args[0]).Root.Element("policy");RebirthTheorySoloLockpickRelevance model;Check(RebirthTheorySoloLockpickRelevance.TryReadPolicy(policy,out model),"actual authoring");Check(model.TryDifficulty(15,out var n)&&Math.Abs(n-50)<.0001,"authored standard reference");Check(model.TryDifficulty(3.75f,out n)&&Math.Abs(n-25)<.0001,"short original lock");Check(model.TryDifficulty(26.666667f,out n)&&Math.Abs(n-66.666667)<.001,"hard native lock");Check(model.TryDifficulty(100,out n)&&n==75,"authored relevance cap");Check(!model.TryDifficulty(float.NaN,out n)&&!model.TryDifficulty(float.PositiveInfinity,out n)&&!model.TryDifficulty(0,out n)&&!model.TryDifficulty(-1,out n),"nonfinite/nonwork");Check(RebirthTheorySoloLockpickRelevance.TryReadPolicy(new XElement("policy"),out model)&&model.TryDifficulty(15,out n)&&n==50,"legacy defaults");var bad=new XElement(policy);bad.Attribute("lockpick_maximum_theory_difficulty").Remove();Check(!RebirthTheorySoloLockpickRelevance.TryReadPolicy(bad,out model),"partial authoring denied");bad=new XElement(policy);bad.SetAttributeValue("lockpick_reference_native_seconds","NaN");Check(!RebirthTheorySoloLockpickRelevance.TryReadPolicy(bad,out model),"nonfinite authoring denied");bad=new XElement(policy);bad.SetAttributeValue("lockpick_reference_native_seconds",0);Check(!RebirthTheorySoloLockpickRelevance.TryReadPolicy(bad,out model),"zero time reference denied");bad=new XElement(policy);bad.SetAttributeValue("lockpick_maximum_theory_difficulty",40);Check(!RebirthTheorySoloLockpickRelevance.TryReadPolicy(bad,out model),"maximum below reference denied");bad=new XElement(policy);bad.SetAttributeValue("lockpick_reference_theory_difficulty",101);Check(!RebirthTheorySoloLockpickRelevance.TryReadPolicy(bad,out model),"reference beyond Theory denied");Console.WriteLine(count+" PASS actual authored native-lock-time Theory relevance");}}